grid=[[5]*22 for _ in range(22)]
objects=[(3,0,8,9),(16,0,8,2),(12,5,8,1),(9,12,2,3),(17,12,2,9),(5,17,2,4)]
for r,c,bg,fg in objects:
    for i in range(5):
        for j in range(5):
            grid[r+i][c+j]=fg if 1<=i<=3 and 1<=j<=3 else bg
print('\n'.join(' '.join(map(str,row)) for row in grid))

